"В коробке N конфет. Мира съела N/N. Сколько это?": "Қутида N конфет бар. Мира N/N қисмини йеди. Бу қанчә?",
"В коробке N конфет. Мира съела одну восьмую часть. Сколько это?": "Қутида N конфет бар. Мира сәккиздин бирини йеди. Бу қанчә?",
"В коробке N конфет. Мира съела одну десятую часть. Сколько это?": "Қутида N конфет бар. Мира ондин бирини йеди. Бу қанчә?",
"В коробке N конфет. Мира съела одну пятую часть. Сколько это?": "Қутида N конфет бар. Мира бәштин бирини йеди. Бу қанчә?",
"В коробке N конфет. Мира съела одну шестую часть. Сколько это?": "Қутида N конфет бар. Мира алтидин бирини йеди. Бу қанчә?",
"В коробке N конфет. Мира съела половину. Сколько это?": "Қутида N конфет бар. Мира йеримини йеди. Бу қанчә?",
"В коробке N конфет. Мира съела треть. Сколько это?": "Қутида N конфет бар. Мира үчтин бирини йеди. Бу қанчә?",
