"В коробке N страниц. Айша прочитала N/N. Сколько это?": "Қутида N бәт бар. Айша N/N қисмини оқуди. Бу қанчә?",
"В коробке N страниц. Айша прочитала одну восьмую часть. Сколько это?": "Қутида N бәт бар. Айша сәккиздин бирини оқуди. Бу қанчә?",
