"Считаем сотнями: N сотни + N сотен = N сот. Это N.": "Йүзлүкләп санаймиз: N йүзлүк + N йүзлүк = N йүзлүк. Бу N.",
"Считаем сотнями: N сотни + N сотни = N сот. Это N.": "Йүзлүкләп санаймиз: N йүзлүк + N йүзлүк = N йүзлүк. Бу N.",
"Считаем сотнями: N сотни + N сотня = N сот. Это N.": "Йүзлүкләп санаймиз: N йүзлүк + N йүзлүк = N йүзлүк. Бу N.",
"Считаем сотнями: N сотни − N сотни = N сот. Это N.": "Йүзлүкләп санаймиз: N йүзлүк − N йүзлүк = N йүзлүк. Бу N.",
"Считаем сотнями: N сотни − N сотня = N сот. Это N.": "Йүзлүкләп санаймиз: N йүзлүк − N йүзлүк = N йүзлүк. Бу N.",
"Считаем сотнями: N сотня + N сотен = N сот. Это N.": "Йүзлүкләп санаймиз: N йүзлүк + N йүзлүк = N йүзлүк. Бу N.",
"Считаем сотнями: N сотня + N сотни = N сот. Это N.": "Йүзлүкләп санаймиз: N йүзлүк + N йүзлүк = N йүзлүк. Бу N.",
"Считаем тысячами: каждый раз на N больше. Дальше N.": "Миңлап санаймиз: һәр қетим N дин көп. Кейин N.",
