"Только первая группа: N, общая часть: N. Всего N + N = N": "Пәқәт биринчи гуруппа: N, ортақ қисим: N. Жәми N + N = N",
"Томирис собрал N ракушек, а его сестра — на N больше. Сколько ракушек собрала сестра?": "Томирис N чиғанақ терди, униң сиңлиси болса N көп терди. Сиңлиси нәччә чиғанақ терди?",
