"Тонна, грамм, километр, миллиметр": "Тонна, грамм, километр, миллиметр",
"Точка A: вправо на N, вверх на N. Координаты (N; N).": "A нуқтиси: оңға N, юқириға N. Координатлири (N; N).",
"Точка A: идём вправо на N и вверх на N. Координаты N и N.": "A нуқтиси: оңға N вә юқириға N маңимиз. Координатлири N вә N.",
"Точка B: вправо на N, вверх на N. Координаты (N; N).": "B нуқтиси: оңға N, юқириға N. Координатлири (N; N).",
"Точка B: идём вправо на N и вверх на N. Координаты N и N.": "B нуқтиси: оңға N вә юқириға N маңимиз. Координатлири N вә N.",
"Точка C: вправо на N, вверх на N. Координаты (N; N).": "C нуқтиси: оңға N, юқириға N. Координатлири (N; N).",
"Точка C: идём вправо на N и вверх на N. Координаты N и N.": "C нуқтиси: оңға N вә юқириға N маңимиз. Координатлири N вә N.",
"Точки A, B, C и D — вершины прямоугольника. Чему равен его периметр в клетках?": "A, B, C вә D нуқтилири тик төртбулуңниң чоққилири. Униң периметри катәкләрдә қанчә?",
"Точки на одной высоте. Считаем клетки по горизонтали: N − N = N": "Нуқтилар бир егизликтә. Катәкләрни көлдәнәң санаймиз: N − N = N",
"Точки стоят на одной высоте. Считаем клетки: N минус N будет N.": "Нуқтилар бир егизликтә туриду. Катәкләрни санаймиз: N дин N ни елисақ N болиду.",
"Ты купил N ручек по N тенге и заплатил N тенге. Сколько сдачи?": "Сән N қәләмни N теңгидин сетивелип, N теңгә төлидиң. Қайтим қанчә?",
"Ты купил N ручки по N тенге и заплатил N тенге. Сколько сдачи?": "Сән N қәләмни N теңгидин сетивелип, N теңгә төлидиң. Қайтим қанчә?",
"У Али N карточек, у Данияра на N меньше. Сколько у Данияра? N − N = N. А вместе: N + N = N.": "Алиниң N карточкиси бар, Даниярда N аз. Данияр да қанчә бар? N − N = N. Биллә: N + N = N.",
"У Али N марок, а у Айи на N марок больше. Сколько марок у Айи?": "Алиниң N маркиси бар, Айяниң болса N марка көп. Айяда нәччә марка бар?",
"У Али N марок, у Айи в N раза больше. Сколько марок у Айи?": "Алиниң N маркиси бар, Айяда N һәссә көп. Айяда нәччә марка бар?",
"У Али N марок, у Айи в N раза меньше. Сколько марок у Айи?": "Алиниң N маркиси бар, Айяда N һәссә аз. Айяда нәччә марка бар?",
"У Алии N наклеек, у Тимура на N меньше. Сколько наклеек у Тимура?": "Алияниң N чаплимиси бар, Тимурда N аз. Тимурда нәччә чаплима бар?",
"У Алмаса N рубашки и N пары шорт. Сколько разных нарядов можно составить?": "Алмасниң N көйниги вә N шортиси бар. Нәччә хил кийим жүрүлүшини түзүшкә болиду?",
"У Данияра N марки, а у Ерлана — в N раз больше. Сколько марок у Ерлана?": "Даниярниң N маркиси бар, Ерланниң болса N һәссә көп. Ерланда нәччә марка бар?",
"У Данияра N марки, а у Ерлана — в N раза больше. Сколько марок у Ерлана?": "Даниярниң N маркиси бар, Ерланниң болса N һәссә көп. Ерланда нәччә марка бар?",
"У Данияра N марок, а у Ерлана — в N раз больше. Сколько марок у Ерлана?": "Даниярниң N маркиси бар, Ерланниң болса N һәссә көп. Ерланда нәччә марка бар?",
"У Данияра N марок, а у Ерлана — в N раза больше. Сколько марок у Ерлана?": "Даниярниң N маркиси бар, Ерланниң болса N һәссә көп. Ерланда нәччә марка бар?",
"У какого столбика значение самое большое?": "Қайси устунниң қиммити әң чоң?",
"У какого столбика значение самое маленькое?": "Қайси устунниң қиммити әң кичик?",
"У квадрата все стороны равны: N · N = N см": "Квадратниң һәммә тәрипи тәң: N · N = N см",
